// @generated by:gauntlet run:godseye-local-backend
import { randomBytes, randomUUID } from "node:crypto";
import { readFile, unlink } from "node:fs/promises";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { committedFile, fileDigest, initiateFile } from "./backend-file-fixture.js";
import { type BackendFixture, backendFixture } from "./backend-fixture.js";

describe("actual application file/auth/config recovery into a new held environment", () => {
  let source: BackendFixture, target: BackendFixture | undefined;
  beforeEach(async () => {
    source = await backendFixture();
  });
  afterEach(async () => {
    await source.close();
    await target?.close();
  });
  async function destination() {
    target = await backendFixture({
      scope: { projectId: source.scope.projectId, environmentId: randomUUID() },
    });
    target.lifecycle.available = false;
    return target;
  }

  it("T-AC-57 T-AC-62 restores real bytes, identity and captured configuration while retaining a durable activation hold", async () => {
    const user = await source.register();
    const committed = await committedFile(source, user.cookie, "recoverable private bytes");
    await initiateFile(source, user.cookie, new Uint8Array(4));
    const archive = join(source.root, "recovery-archive");
    const before = Date.now();
    const exported = await source.runtime.exportRecovery({ directory: archive });
    const after = Date.now();
    expect(exported).toMatchObject({
      scope: source.scope,
      files: 1,
      users: 1,
      activationAllowed: false,
    });
    expect(new Date(exported.capturedAt).getTime()).toBeGreaterThanOrEqual(before);
    expect(new Date(exported.capturedAt).getTime()).toBeLessThanOrEqual(after);
    expect(exported.timeCoverage).toMatchObject({
      clockDomain: "local-runtime",
      postgresRecoveryPointAt: null,
      gapAssessment: "external-recovery-point-unknown",
      activationAllowed: false,
    });
    for (const value of [
      exported.timeCoverage.databaseCapturedAt,
      exported.timeCoverage.configurationCapturedAt,
      exported.timeCoverage.fileCopyStartedAt,
      exported.timeCoverage.fileCopyCompletedAt,
    ]) {
      expect(new Date(value).getTime()).toBeGreaterThanOrEqual(before);
      expect(new Date(value).getTime()).toBeLessThanOrEqual(after);
    }
    expect(Date.parse(exported.timeCoverage.fileCopyCompletedAt)).toBeGreaterThanOrEqual(
      Date.parse(exported.timeCoverage.fileCopyStartedAt),
    );
    await source.register({
      name: "After recovery point",
      email: "after-snapshot@example.test",
      password: "Synthetic-later-passphrase-192!",
    });
    const late = await committedFile(source, user.cookie, "after recovery point");
    const restored = await destination();
    const outcome = await restored.runtime.importRecovery({
      directory: archive,
      sourceAuthMaterial: source.authMaterial,
    });
    expect(outcome).toMatchObject({
      sourceScope: source.scope,
      scope: restored.scope,
      capturedAt: exported.capturedAt,
      recoveryHeld: true,
      activationAllowed: false,
      sessionsRestored: false,
      externalEffectsReconciled: false,
    });
    expect(outcome.configuration).toMatchObject({
      baseUrl: source.baseUrl,
      registrationEnabled: true,
      trustedOrigins: [source.baseUrl],
    });
    expect(outcome.timeCoverage).toEqual(exported.timeCoverage);
    const snapshot = await restored.runtime.snapshot();
    expect(snapshot).toMatchObject({
      scope: restored.scope,
      recoveryHeld: true,
      auth: { users: 1, sessionsRestorable: false },
      coverage: {
        files: true,
        auth: true,
        configuration: true,
        externalEffects: false,
        activationAllowed: false,
      },
    });
    expect(snapshot.files).toHaveLength(1);
    expect(snapshot.timeCoverage).toMatchObject({
      clockDomain: "local-runtime",
      postgresRecoveryPointAt: null,
      gapAssessment: "external-recovery-point-unknown",
      activationAllowed: false,
    });
    expect(snapshot.files[0]).toMatchObject({
      id: committed.file.id,
      physical: "verified",
      sha256: fileDigest(committed.bytes),
    });
    expect(await readFile(join(restored.filesRoot, committed.file.id))).toEqual(
      Buffer.from(committed.bytes),
    );
    await expect(readFile(join(restored.filesRoot, late.file.id))).rejects.toMatchObject({
      code: "ENOENT",
    });
    expect(await readFile(join(source.filesRoot, committed.file.id))).toEqual(
      Buffer.from(committed.bytes),
    );
    restored.lifecycle.available = true;
    expect(
      (await restored.request("/auth/get-session", { headers: { cookie: user.cookie } })).status,
    ).toBe(423);
    await restored.restart();
    expect((await restored.request("/health")).status).toBe(423);
    expect((await restored.runtime.snapshot()).recoveryHeld).toBe(true);
  });

  it("T-AC-57 reports missing committed bytes and refuses to call an incomplete export recoverable", async () => {
    const user = await source.register();
    const { file } = await committedFile(source, user.cookie);
    await unlink(join(source.filesRoot, file.id));
    const snapshot = await source.runtime.snapshot();
    expect(snapshot.coverage.files).toBe(false);
    expect(snapshot.files[0]).toMatchObject({ id: file.id, physical: "missing" });
    await expect(
      source.runtime.exportRecovery({ directory: join(source.root, "missing-archive") }),
    ).rejects.toMatchObject({ code: "RECOVERY_INCOMPLETE" });
  });

  it("T-AC-57 refuses unauthenticated recovery material and never enables the destination", async () => {
    await source.register();
    const archive = join(source.root, "recovery-archive");
    await source.runtime.exportRecovery({ directory: archive });
    const restored = await destination();
    await expect(
      restored.runtime.importRecovery({
        directory: archive,
        sourceAuthMaterial: randomBytes(48).toString("base64url"),
      }),
    ).rejects.toMatchObject({ code: "RECOVERY_INTEGRITY" });
    expect((await restored.runtime.snapshot()).auth.users).toBe(0);
    expect((await restored.request("/health")).status).toBe(423);
  });

  it("T-AC-57 refuses import into a live destination before copying any user or file", async () => {
    await source.register();
    const archive = join(source.root, "recovery-archive");
    await source.runtime.exportRecovery({ directory: archive });
    const restored = await destination();
    restored.lifecycle.available = true;
    await expect(
      restored.runtime.importRecovery({
        directory: archive,
        sourceAuthMaterial: source.authMaterial,
      }),
    ).rejects.toMatchObject({ code: "RECOVERY_HOLD_REQUIRED" });
    expect((await restored.runtime.snapshot()).auth.users).toBe(0);
  });

  it("T-AC-57 refuses an archive from another project without adopting its identity", async () => {
    await source.register();
    const archive = join(source.root, "recovery-archive");
    await source.runtime.exportRecovery({ directory: archive });
    target = await backendFixture();
    target.lifecycle.available = false;
    await expect(
      target.runtime.importRecovery({
        directory: archive,
        sourceAuthMaterial: source.authMaterial,
      }),
    ).rejects.toMatchObject({ code: "RECOVERY_SCOPE_MISMATCH" });
    expect((await target.runtime.snapshot()).auth.users).toBe(0);
  });
});
